module parallel2serial (
    input clk, 
    input rst_n, 
    input [3:0] d, 
    output valid_out, 
    output dout
);
// Sequential logic for counter and data storage
reg [1:0] cnt;
reg [3:0] data;
reg valid;
// Assign dout to the MSB of the data register
assign dout = data[3];
// Assign valid_out to the valid register
assign valid_out = valid;
// Always block triggered on the positive edge of clk or negative edge of rst_n
always @(posedge clk or negedge rst_n) begin
    // If reset signal is low, initialize cnt to 0
    if (~rst_n) begin
        cnt <= 2'b00;
    end else begin
        // If cnt is equal to 3, update data with input d, reset cnt to 0, and set valid to 1
        if (cnt == 2'b11) begin
            data <= d;
            cnt <= 2'b00;
            valid <= 1'b1;
        end else begin
            // Otherwise, increment cnt by 1, set valid to 0, and shift data to the left by 1 bit
            cnt <= cnt + 1;
            valid <= 1'b0;
            data <= {data[2:0], data[3]};
        end
    end
end
endmodule
